10	extern int parse_arg(
11	    std::vector<std::string> args, ventus_rtlsim_config_t* config,
12	    std::function<void(std::shared_ptr<Kernel>)> new_kernel, std::vector<std::pair<paddr_t, paddr_t>>* dumpmem_ranges
