22	int main(int argc, char* argv[]) {
23	    spdlog::set_level(spdlog::level::trace);
24	    const char* verilator_argv[] = {
25	        "+verilator+seed+10086",
26	    };
27	
28	    //
29	    // simulation config
30	    //
31	    ventus_rtlsim_config_t sim_config;
32	    ventus_rtlsim_get_default_config(&sim_config);
33	
34	    sim_config.log.console.level = "trace";
35	    sim_config.sim_time_max = 200000;
36	    sim_config.pmem.auto_alloc = true;
37	    sim_config.waveform.enable = false;
38	    sim_config.waveform.time_begin = 0;
39	    sim_config.waveform.time_end = -1;
40	    sim_config.verilator.argc = sizeof(verilator_argv) / sizeof(verilator_argv[0]);
41	    sim_config.verilator.argv = verilator_argv;
42	    ventus_rtlsim_config_t sim_config_1 = sim_config; // not needed
43	    std::vector<std::pair<paddr_t, paddr_t>> dumpmem_ranges;
44	
45	    // parse cmdline args, set sim-config
46	    std::vector<std::string> args;
47	    if (argc == 1) { // Default arguments
48	        puts("[Info] using default cmdline arguments: -f ventus_args.txt");
49	        args.push_back("-f");
50	        args.push_back("ventus_args.txt");
51	    } else {
52	        for (int i = 1; i < argc; i++) {
53	            args.push_back(argv[i]);
54	        }
55	    }
56	    parse_arg(args, &sim_config, nullptr, nullptr);
57	
58	    //
59	    // init Ventus RTLSIM
60	    //
61	    ventus_rtlsim_t* sim = ventus_rtlsim_init(&sim_config);
62	
63	    // parse cmdline arguments, generate kernels, and add them to Ventus RTLSIM
64	    std::function<void(std::shared_ptr<Kernel>)> f_new_kernel = [sim](std::shared_ptr<Kernel> kernel) {
65	        metadata_t metadata = *kernel->get_metadata();
66	        metadata.data = new kernel_load_data_callback_t { .datafile = kernel->m_datafile, .sim = sim };
67	        ventus_rtlsim_add_kernel__delay_data_loading(sim, &metadata, kernel_load_data_callback, nullptr);
68	    };
69	    parse_arg(args, &sim_config_1, f_new_kernel, &dumpmem_ranges);
70	
71	    //
72	    // Run simulation, each step stands for 1 simulation time-unit
73	    //
74	    const ventus_rtlsim_step_result_t* result;
75	    while (1) {
76	        result = ventus_rtlsim_step(sim);
77	        if (result->error || result->idle || result->time_exceed) {
78	            break;
79	        }
80	    }
81	
82	    //
83	    // Finish simulation, release resources
84	    //
85	    if (!result->error && !result->time_exceed && result->idle) {
86	        for (int i = 0; i < 10000; i++) {
87	            ventus_rtlsim_step(sim); // 额外运行一会儿，等待缓存invalidate结束
88	        }
89	    }
90	    for (const auto& range : dumpmem_ranges) { // 命令行参数要求输出的内存内容，每4字节输出1行
91	        paddr_t begin = range.first;
92	        paddr_t end = range.second;
93	        size_t len = (end - begin + 7) / 4 * 4;
94	        std::unique_ptr<uint8_t[]> buffer = std::make_unique<uint8_t[]>(len);
95	        if (!ventus_rtlsim_pmemcpy_d2h(sim, buffer.get(), begin, len)) {
96	            spdlog::error("Failed to dump physical memory [0x{:#x}, 0x{:#x}]", begin, end);
97	            continue;
98	        }
99	        for (paddr_t addr = begin; addr <= end; addr += 4) {
100	            uint32_t word = *(uint32_t*)(buffer.get() + (addr - begin));
101	            fmt::print("dump-mem: mem[0x{:08X} +: 4] = 0x{:08X}\n", addr, word);
102	        }
103	    }
104	    ventus_rtlsim_finish(sim, false);
105	
106	    return 0;
107	}
