109	void kernel_load_data_callback(const metadata_t* metadata) {
110	    kernel_load_data_callback_t* cb_data = (kernel_load_data_callback_t*)metadata->data;
111	    std::ifstream file(cb_data->datafile);
112	    if (!file.is_open()) {
113	        spdlog::critical("Failed to open .data file: {}", cb_data->datafile.c_str());
114	        assert(0);
115	    }
116	
117	    std::string line;
118	    int bufferIndex = 0;
119	    std::vector<uint8_t> buffer;
120	    for (int bufferIndex = 0; bufferIndex < metadata->num_buffer; bufferIndex++) {
121	        assert(metadata->buffer_size[bufferIndex] % 4 == 0);
122	        buffer.reserve(metadata->buffer_size[bufferIndex]); // 提前分配空间
123	        int readbytes = 0;
124	        while (readbytes < metadata->buffer_size[bufferIndex]) {
125	            std::getline(file, line);
126	            for (int i = line.length(); i > 0; i -= 2) {
127	                std::string hexChars = line.substr(i - 2, 2);
128	                uint8_t byte = std::stoi(hexChars, nullptr, 16);
129	                buffer.push_back(byte);
130	            }
131	            readbytes += 4;
132	        }
133	        ventus_rtlsim_pmemcpy_h2d(cb_data->sim, metadata->buffer_base[bufferIndex], buffer.data(), readbytes);
134	        buffer.clear();
135	    }
136	    std::getline(file, line);
137	    for (const char* ptr = line.c_str(); *ptr != '\0'; ptr++) {
138	        assert(*ptr == '0');
139	    }
140	    assert(file.eof());
141	
142	    file.close();
143	    spdlog::trace(fmt::format("kernel{} {} data loaded from file", metadata->kernel_id, metadata->name));
144	}
