27	//
28	// cleanup at exit
29	//
30	static std::vector<ventus_rtlsim_t*> g_instances;
31	
32	// cleanup: mainly for Verilator FST waveform dump
33	// tfp->close() is necessary to save complete waveform to file
34	//  or the fst file may be corrupted, or lose some data at the end
35	//  in this case, a .fst.hier file appears. 
36	static void cleanup() {
37	    for (auto* sim : g_instances) {
38	        if (sim->tfp)
39	            sim->tfp->close(); // save waveform to file
40	        // No need to delete tfp, the process is exiting
41	        // delete sim->tfp; // This will cause segfault sometimes, why?
42	        sim->tfp = nullptr;
43	    }
44	    g_instances.clear();
45	}
