67	// convert log level string to spdlog level enum
68	static spdlog::level::level_enum get_log_level(const char* level) {
69	    if (level == nullptr) {
70	        // set to default level later
71	    } else if (strcmp(level, "trace") == 0) {
72	        return spdlog::level::trace;
73	    } else if (strcmp(level, "debug") == 0) {
74	        return spdlog::level::debug;
75	    } else if (strcmp(level, "info") == 0) {
76	        return spdlog::level::info;
77	    } else if (strcmp(level, "warn") == 0) {
78	        return spdlog::level::warn;
79	    } else if (strcmp(level, "error") == 0) {
80	        return spdlog::level::err;
81	    } else if (strcmp(level, "critical") == 0) {
82	        return spdlog::level::critical;
83	    }
84	    std::cerr << "Log level unrecognized: \"" << level << "\", set to default: \"trace\"" << std::endl;
85	    return spdlog::level::trace;
86	}
