88	// log formatter
89	class Formatter_ventus_rtlsim : public spdlog::formatter {
90	public:
91	    Formatter_ventus_rtlsim(std::function<std::string()> callback)
92	        : m_callback(callback) {};
93	
94	    void format(const spdlog::details::log_msg& msg, spdlog::memory_buf_t& dst) override {
95	        std::string basic_info = fmt::format("[RTL {0:>8}]", spdlog::level::to_string_view(msg.level));
96	        std::string cb_info = m_callback ? m_callback() : "";
97	        std::string newline = "\n";
98	        dst.append(basic_info.data(), basic_info.data() + basic_info.size());
99	        dst.append(cb_info.data(), cb_info.data() + cb_info.size());
100	        dst.append(msg.payload.begin(), msg.payload.end());
101	        dst.append(newline.data(), newline.data() + newline.size());
102	    }
103	
104	    std::unique_ptr<spdlog::formatter> clone() const override {
105	        return std::make_unique<Formatter_ventus_rtlsim>(m_callback);
106	    }
107	
108	private:
109	    std::function<std::string()> m_callback;
110	};
