116	void ventus_rtlsim_t::constructor(const ventus_rtlsim_config_t* config_) {
117	    // copy and check sim config
118	    config = *config_;
119	    if (config.log.file.enable && config.log.file.filename == nullptr) {
120	        std::cerr << "Log file name not given, set to default: logs/ventus_rtlsim.log" << std::endl;
121	        config.log.file.filename = "logs/ventus_rtlsim.log";
122	    }
123	    if (config.waveform.enable && config.waveform.filename == NULL) {
124	        std::cerr << "waveform enabled but fst filename is NULL, set to default: logs/ventus_rtlsim.fst" << std::endl;
125	        config.waveform.filename = "logs/ventus_rtlsim.fst";
126	    }
127	    if (config.snapshot.enable && config.snapshot.filename == NULL) {
128	        std::cerr << "waveform enabled but fst filename is NULL, set to default: logs/ventus_rtlsim.snapshot.fst"
129	                  << std::endl;
130	        config.snapshot.filename = "logs/ventus_rtlsim.snapshot.fst";
131	    }
132	    config.verilator.argc = 0;
133	    config.verilator.argv = nullptr;
134	
135	    // init logger
136	    try {
137	        std::vector<spdlog::sink_ptr> sinks;
138	        if (config.log.file.enable) {
139	            auto file_sink = std::make_shared<spdlog::sinks::basic_file_sink_mt>(config.log.file.filename);
140	            file_sink->set_level(get_log_level(config.log.file.level));
141	            sinks.push_back(file_sink);
142	        }
143	        if (config.log.console.enable) {
144	            auto console_sink = std::make_shared<spdlog::sinks::stdout_color_sink_mt>();
145	            console_sink->set_level(get_log_level(config.log.console.level));
146	            sinks.push_back(console_sink);
147	        }
148	        logger = std::make_shared<spdlog::logger>("VentusRTLsim_logger", sinks.begin(), sinks.end());
149	#ifdef ENABLE_GVM
150	        gvm.logger = logger;
151	#endif // ENABLE_GVM
152	        logger->set_level(get_log_level(config.log.level));
153	        logger->flush_on(spdlog::level::err);
154	
155	        // set logger formatter
156	        auto func_log_prefix
157	            = [&contextp = std::as_const(contextp)]() -> std::string { return fmt::format("@{} ", contextp->time()); };
158	        auto formatter = std::make_unique<Formatter_ventus_rtlsim>(func_log_prefix);
159	        logger->set_formatter(std::move(formatter));
160	
161	        // set logger error handler
162	        auto func_log_error_handler = [](const std::string& msg) {
163	            std::cerr << "VentusRTLsim_logger error: " << msg << std::endl;
164	            std::abort();
165	        };
166	        logger->set_error_handler(func_log_error_handler);
167	    } catch (const spdlog::spdlog_ex& ex) {
168	        std::cerr << "Log initialization failed: " << ex.what() << std::endl;
169	        exit(1);
170	    }
171	
172	    // init Verilator simulation context
173	    contextp = new VerilatedContext;
174	    contextp->debug(0);
175	    contextp->randReset(0);
176	    contextp->traceEverOn(true);
177	    snapshots.is_child = false;
178	    snapshots.children_pid.clear();
179	
180	    // load Verilator runtime arguments
181	    const char* verilator_runtime_args_default[] = { "+verilator+seed+10086" };
182	    contextp->commandArgsAdd(
183	        sizeof(verilator_runtime_args_default) / sizeof(verilator_runtime_args_default[0]),
184	        verilator_runtime_args_default
185	    );
186	    if (config_->verilator.argc > 0 && config_->verilator.argv)
187	        contextp->commandArgs(config_->verilator.argc, config_->verilator.argv);
188	
189	    // instantiate hardware
190	    dut = new Vdut();
191	    cta = new Cta(logger);
192	    pmem = std::make_unique<PhysicalMemory>(config.pmem.auto_alloc, config.pmem.pagesize, logger);
193	    need_icache_invalidate = false;
194	
195	    // waveform traces (FST)
196	    if (config.waveform.enable) {
197	        tfp = new VerilatedFstC;
198	        dut->trace(tfp, config.waveform.levels);
199	        tfp->open(config.waveform.filename);
200	        // sig abort
201	        struct sigaction sa;
202	        sa.sa_handler = signal_abort_handler;
203	        sa.sa_flags = 0;
204	        sigemptyset(&sa.sa_mask);
205	        struct sigaction sa_old;
206	        sigaction(SIGABRT, &sa, &sa_old);
207	        g_sigabort_old = sa_old;
208	        // sig interrupt
209	        sa.sa_handler = signal_interrupt_handler;
210	        sigaction(SIGINT, &sa, nullptr);
211	    } else {
212	        tfp = nullptr;
213	    }
214	
215	    // push into global instances, prepare cleanup at exit
216	    g_instances.push_back(this);
217	
218	    // get ready to run
219	    snapshot_fork(); // initial snapshot at sim_time = 0
220	    dut_reset();
221	}
