223	const ventus_rtlsim_step_result_t* ventus_rtlsim_t::step() {
224	    step_status.error = contextp->gotFinish() || contextp->gotError();
225	    step_status.time_exceed = contextp->time() >= config.sim_time_max;
226	    step_status.idle = cta->is_idle();
227	    if (step_status.error || step_status.time_exceed) {
228	        return &step_status;
229	    }
230	    bool sim_got_error = false;
231	
232	    //
233	    // clock step
234	    //
235	    contextp->timeInc(HALF_CYCLE_TIME);
236	    dut->clock = !dut->clock;
237	
238	    //
239	    // Delta time before negedge(clk)
240	    // apply outside stimuli to DUT
241	    //
242	    if (dut->clock == 0) {
243	        // Thread-block dispatch to GPU (stimuli)
244	        cta->apply_to_dut(dut);
245	
246	        // Thread-block return from GPU (stimuli)
247	        dut->io_host_rsp_ready = 1;
248	
249	        // Assert Verilated memory IO type: must be VlWide
250	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_rd_data)>::type>::value, "Check io_mem type");
251	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_wr_data)>::type>::value, "Check io_mem type");
252	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_wr_mask)>::type>::value, "Check io_mem type");
253	
254	        // Physical memory access - read
255	        if (dut->io_mem_rd_en) {
256	            uint64_t rd_addr = dut->io_mem_rd_addr;
257	            pmem->read(rd_addr, dut->io_mem_rd_data.data(), dut->io_mem_rd_data.Words * 4);
258	        }
259	        // Physical memory access - write
260	        if (dut->io_mem_wr_en) {
261	            uint64_t wr_addr = dut->io_mem_wr_addr;
262	            bool* mask = new bool[dut->io_mem_wr_mask.Words * 32];
263	            for (int idx = 0; idx < dut->io_mem_wr_mask.Words; idx++) {
264	                uint32_t mask_raw = dut->io_mem_wr_mask[idx];
265	                for (int bit = 0; bit < 32; bit++) {
266	                    mask[bit + idx * 32] = mask_raw & 0x1;
267	                    mask_raw >>= 1;
268	                }
269	            }
270	            if (!pmem->write(wr_addr, dut->io_mem_wr_data.data(), mask, dut->io_mem_wr_data.Words * 4)) {
271	                sim_got_error = true;
272	            }
273	            delete[] mask;
274	        }
275	    }
276	
277	    //
278	    // Delta time before posedge(clk)
279	    // Check for Valid-Ready fire
280	    //
281	    if (dut->clock == 1) {
282	        // Thread-block dispatch to GPU (handshake OK)
283	        if (dut->io_host_req_valid && dut->io_host_req_ready) {
284	            uint32_t wg_id = dut->io_host_req_bits_host_wg_id;
285	            uint32_t wg_idx, kernel_id;
286	            std::string kernel_name;
287	            assert(cta->wg_get_info(kernel_name, kernel_id, wg_idx));
288	            cta->wg_dispatched();
289	            logger->debug(fmt::format(
290	                "block{0:<2} dispatched to GPU (kernel{1:<2} {2} block{3:<2})", wg_id, kernel_id, kernel_name, wg_idx
291	            ));
292	        }
293	        // Thread-block return from GPU (handshake OK)
294	        if (dut->io_host_rsp_valid && dut->io_host_rsp_ready) {
295	            uint32_t wg_id = dut->io_host_rsp_bits_inflight_wg_buffer_host_wf_done_wg_id;
296	            cta->wg_finish(wg_id);
297	        }
298	        dut->io_icache_invalidate = need_icache_invalidate;
299	        need_icache_invalidate = false;
300	    }
301	
302	    //
303	    // Eval
304	    //
305	    dut->eval();
306	    waveform_dump();
307	
308	    //
309	    // Abort?
310	    //
311	    if (g_interrupt) {
312	        destructor(false);
313	        std::exit(130);
314	    }
315	    if (g_aborted) {
316	        destructor(false);
317	        if (g_sigabort_old.has_value()) {
318	            sigaction(SIGABRT, &(g_sigabort_old.value()), nullptr);
319	            g_sigabort_old = std::nullopt;
320	            raise(SIGABRT); // 让进程按默认方式终止，允许Coredump
321	        } else {
322	            std::exit(EXIT_FAILURE);
323	        }
324	    }
325	
326	    //
327	    // Clock output
328	    //
329	    if (contextp->time() % 10000 == 0) {
330	        logger->debug("");
331	    }
332	
333	    //
334	    // snapshot fork
335	    //
336	    step_status.error = sim_got_error || contextp->gotFinish() || contextp->gotError();
337	    step_status.time_exceed = contextp->time() >= config.sim_time_max;
338	    step_status.idle = cta->is_idle();
339	    if (!step_status.time_exceed && !step_status.error && contextp->time() % config.snapshot.time_interval == 0) {
340	        snapshot_fork();
341	    }
342	
343	#ifdef ENABLE_GVM
344	    if (contextp->time() % 2 == 1) {
345	        gvm.getDut();
346	        gvm.gvmStep();
347	    }
348	#endif // ENABLE_GVM
349	
350	    return &step_status;
351	}
