522	void ventus_rtlsim_t::dut_reset() const {
523	    assert(dut && contextp);
524	    contextp->time(0);
525	    dut->io_host_req_valid = 0;
526	    dut->io_host_rsp_ready = 0;
527	    dut->reset = 1;
528	    dut->clock = 0;
529	    dut->eval();
530	    waveform_dump();
531	
532	    contextp->timeInc(HALF_CYCLE_TIME);
533	    dut->clock = 1;
534	    dut->eval();
535	    waveform_dump();
536	
537	    contextp->timeInc(HALF_CYCLE_TIME);
538	    dut->clock = 0;
539	    dut->eval();
540	    waveform_dump();
541	
542	    contextp->timeInc(HALF_CYCLE_TIME);
543	    dut->clock = 1;
544	    dut->eval();
545	    waveform_dump();
546	
547	    contextp->timeInc(HALF_CYCLE_TIME);
548	    dut->clock = 0;
549	    dut->reset = 0;
550	    dut->eval();
551	    waveform_dump();
552	    logger->trace("Hardware reset ok");
553	}
