44	bool Cta::apply_to_dut(Vdut* dut) {
45	    assert(m_kernel_idx_dispatching < 0 || m_kernel_idx_dispatching < m_kernels.size());
46	    std::shared_ptr<Kernel> kernel = (m_kernel_idx_dispatching == -1) ? nullptr : m_kernels[m_kernel_idx_dispatching];
47	    assert(m_kernel_idx_dispatching == -1 || kernel);
48	
49	    // 当前kernel分派结束后，切换到下一个kernel
50	    if (kernel == nullptr || !kernel->is_dispatching()) {
51	        // TODO: 暂未实现虚拟内存，目前需要等待当前kernel完全结束才能开始分派下一个kernel
52	        // if (m_kernels.size() == m_kernel_idx_dispatching + 1) { // 无下一个kernel，不分派
53	        if (m_kernels.size() == m_kernel_idx_dispatching + 1 || (kernel && !kernel->is_finished())) {
54	            // 需等待当前kernel或者无下一个kernel，不分派WG
55	            dut->io_host_req_valid = false;
56	            return false;
57	        } else {
58	            // 激活下一个kernel，准备分派其线程块
59	            kernel = m_kernels[++m_kernel_idx_dispatching];
60	            assert(kernel && !kernel->is_activated() && !kernel->is_finished());
61	            assert(m_kernel_wgid_base_next <= 0xEFFFFFFF); // 当前实现中线程块ID不会回收，需防止其溢出
62	            kernel->activate(m_kernel_id_next++, m_kernel_wgid_base_next);
63	            m_kernel_wgid_base_next += kernel->get_num_wg();
64	        }
65	    }
66	
67	    // Get WG to dispatch and apply to DUT
68	    if (kernel && kernel->is_dispatching()) {
69	        dut->io_host_req_valid = true;
70	        uint32_t idx_in_kernel = kernel->get_next_wg_idx_in_kernel();
71	        dim3_t kernel_size_3d = kernel->get_num_wg_3d();
72	        dut->io_host_req_bits_host_wg_id = kernel->get_next_wgid();
73	        // TODO: temporary solution, need to be fixed
74	        // RTL uses kernel_size_3d as wg_id_3d currently
75	        dim3_t wgidx_3d = kernel->get_next_wg_idx3d_in_kernel();
76	        dut->io_host_req_bits_host_kernel_size_3d_0 = wgidx_3d.x;
77	        dut->io_host_req_bits_host_kernel_size_3d_1 = wgidx_3d.y;
78	        dut->io_host_req_bits_host_kernel_size_3d_2 = wgidx_3d.z;
79	        dut->io_host_req_bits_host_num_wf = kernel->get_num_wf();
80	        dut->io_host_req_bits_host_wf_size = kernel->get_num_thread();
81	        dut->io_host_req_bits_host_lds_size_total = kernel->get_num_lds();
82	        dut->io_host_req_bits_host_sgpr_size_total = kernel->get_num_sgpr_per_wf() * kernel->get_num_wf();
83	        dut->io_host_req_bits_host_vgpr_size_total = kernel->get_num_vgpr_per_wf() * kernel->get_num_wf();
84	        dut->io_host_req_bits_host_sgpr_size_per_wf = kernel->get_num_sgpr_per_wf();
85	        dut->io_host_req_bits_host_vgpr_size_per_wf = kernel->get_num_vgpr_per_wf();
86	        dut->io_host_req_bits_host_pds_size_per_wf = kernel->get_num_pds_per_thread() * kernel->get_num_thread();
87	        dut->io_host_req_bits_host_start_pc = kernel->get_start_pc();
88	        dut->io_host_req_bits_host_csr_knl = kernel->get_csr_baseaddr();
89	        dut->io_host_req_bits_host_gds_baseaddr = kernel->get_gds_baseaddr();
90	        dut->io_host_req_bits_host_pds_baseaddr = kernel->get_pds_baseaddr()
91	            + idx_in_kernel * kernel->get_num_wf() * kernel->get_num_thread() * kernel->get_num_pds_per_thread();
92	        dut->io_host_req_bits_host_gds_size_total = 0; // useless
93	        return true;
94	    }
95	    assert(0);
96	}
