98	void Cta::wg_finish(uint32_t wgid) {
99	    for (auto it = m_kernels.begin(); it != m_kernels.end(); it++) {
100	        std::shared_ptr<Kernel> kernel = *it;
101	        uint32_t wg_idx = -1;
102	        if (kernel->is_running() && kernel->is_wg_belonging(wgid, &wg_idx)) { // 寻找wg所属kernel
103	            assert(it <= m_kernels.begin() + m_kernel_idx_dispatching);
104	            kernel->wg_finish(wgid);
105	            logger->debug(
106	                "block{0:<2} finished (kernel{1:<2} {2} block{3:<2})", wgid, kernel->get_kid(), kernel->get_kname(),
107	                wg_idx
108	            );
109	            if (kernel->is_finished()) { // 整个kernel已经结束，删除之
110	                logger->info("kernel{0:<2} {1} finished", kernel->get_kid(), kernel->get_kname());
111	                kernel->deactivate();
112	                m_kernels.erase(it);
113	                m_kernel_idx_dispatching--; // 可能会减至-1
114	            }
115	            return;
116	        }
117	    }
118	    assert(0); // 总应当可以找到WG所属的Kernel
119	}
