11	static void increment_x_then_y_then_z(dim3_t& i, const dim3_t& bound) {
12	    i.x++;
13	    if (i.x >= bound.x) {
14	        i.x = 0;
15	        i.y++;
16	        if (i.y >= bound.y) {
17	            i.y = 0;
18	            if (i.z < bound.z)
19	                i.z++;
20	        }
21	    }
22	}
