24	int Kernel::charToHex(char c) const {
25	    if (c >= '0' && c <= '9')
26	        return c - '0';
27	    else if (c >= 'A' && c <= 'F')
28	        return c - 'A' + 10;
29	    else if (c >= 'a' && c <= 'f')
30	        return c - 'a' + 10;
31	    else
32	        return -1; // Invalid character
33	}
34	bool Kernel::isHexCharacter(char c) const {
35	    return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f');
36	}
37	bool Kernel::no_more_wg_to_dispatch() const {
38	    return (m_next_wg.x >= m_grid_dim.x || m_next_wg.y >= m_grid_dim.y || m_next_wg.z >= m_grid_dim.z);
39	}
40	uint32_t Kernel::get_next_wg_idx_in_kernel() const {
41	    return m_next_wg.x + m_grid_dim.x * m_next_wg.y + m_grid_dim.x * m_grid_dim.y * m_next_wg.z;
42	}
43	uint32_t Kernel::get_next_wgid() const { return m_wgid_base + get_next_wg_idx_in_kernel(); }
44	void Kernel::wg_dispatched() {
45	    assert(is_dispatching());
46	    uint32_t idx = get_next_wg_idx_in_kernel();
47	    if (m_wg_status[idx] != WG_STATUS_WAITING) {
48	        logger->critical("Kernel {} WG {} is dispatched twice", m_kernel_name, idx);
49	    }
50	    assert(m_wg_status[idx] == WG_STATUS_WAITING);
51	    m_wg_status[idx] = WG_STATUS_RUNNING;
52	    increment_x_then_y_then_z(m_next_wg, m_grid_dim);
53	}
