94	void Kernel::readHexFile(const std::string& filename, std::vector<uint64_t>& items, int itemSize) const {
95	    // itemSize为每个数据的比特数，这里为64
96	
97	    std::ifstream file(filename);
98	
99	    if (!file) {
100	        std::cout << "Error opening file: " << filename << std::endl;
101	        return;
102	    }
103	
104	    char c;
105	    int bits = 0;
106	    uint64_t value = 0;
107	    bool leftside = false;
108	
109	    while (file.get(c)) {
110	        if (c == '\n') {
111	            if (bits != 0)
112	                leftside = true;
113	            continue;
114	        }
115	
116	        if (!isHexCharacter(c)) {
117	            std::cout << "Invalid character found: " << c << " in " << filename << std::endl;
118	            continue;
119	        }
120	
121	        int hexValue = charToHex(c);
122	        if (leftside)
123	            value = value | ((uint64_t)hexValue << (92 - bits));
124	        else
125	            value = (value << 4) | hexValue;
126	        bits += 4;
127	
128	        if (bits >= itemSize) {
129	            items.push_back(value);
130	            value = 0;
131	            bits = 0;
132	            leftside = false;
133	        }
134	    }
135	
136	    if (bits > 0) {
137	        std::cout << "Warning: Incomplete item found at the end of the file!" << std::endl;
138	    }
139	
140	    file.close();
141	}
