150	void Kernel::assignMetadata(const std::vector<uint64_t>& metadata, metadata_t& mtd) {
151	    int index = 0;
152	
153	    mtd.startaddr = metadata[index++];
154	
155	    mtd.kernel_id = metadata[index++];
156	
157	    for (int i = 0; i < 3; i++) {
158	        mtd.kernel_size[i] = metadata[index++];
159	    }
160	    m_grid_dim.x = mtd.kernel_size[0];
161	    m_grid_dim.y = mtd.kernel_size[1];
162	    m_grid_dim.z = mtd.kernel_size[2];
163	
164	    mtd.wf_size = metadata[index++];
165	    mtd.wg_size = metadata[index++];
166	    mtd.metaDataBaseAddr = metadata[index++];
167	    mtd.ldsSize = metadata[index++];
168	    mtd.pdsSize = metadata[index++];
169	    mtd.sgprUsage = metadata[index++];
170	    mtd.vgprUsage = metadata[index++];
171	    mtd.pdsBaseAddr = metadata[index++];
172	    mtd.num_buffer = metadata[index++];
173	
174	    mtd.buffer_base = new uint64_t[mtd.num_buffer];
175	
176	    for (int i = 0; i < mtd.num_buffer; i++) {
177	        mtd.buffer_base[i] = metadata[index++];
178	    }
179	
180	    mtd.buffer_size = new uint64_t[mtd.num_buffer];
181	    for (int i = 0; i < mtd.num_buffer; i++) {
182	        mtd.buffer_size[i] = metadata[index++];
183	    }
184	
185	    mtd.buffer_allocsize = new uint64_t[mtd.num_buffer];
186	    for (int i = 0; i < mtd.num_buffer; i++) {
187	        mtd.buffer_allocsize[i] = metadata[index++];
188	    }
189	}
