191	void Kernel::activate(uint32_t kernel_id, uint32_t wgid_base) {
192	    m_kernel_id = kernel_id;
193	    m_wgid_base = wgid_base;
194	    m_metadata.kernel_id = kernel_id;
195	
196	    // If it's needed to load data before running kernel, do it
197	    if (m_load_data_callback)
198	        m_load_data_callback(&m_metadata);
199	
200	    for (const auto wg_status : m_wg_status) {
201	        assert(wg_status == WG_STATUS_WAITING);
202	    }
203	
204	    m_is_activated = true;
205	    logger->trace("kernel{0:>2} {1} activate", get_kid(), get_kname());
206	}
207	void Kernel::deactivate() {
208	    assert(is_activated());
209	    assert(!is_running());
210	    m_is_activated = false;
211	    if (m_finish_callback)
212	        m_finish_callback(&m_metadata);
213	}
214	
215	bool Kernel::is_finished() const {
216	    for (const auto wg_status : m_wg_status) {
217	        if (wg_status != WG_STATUS_FINISHED)
218	            return false;
219	    }
220	    return true;
221	}
222	bool Kernel::is_running() const {
223	    if (!is_activated())
224	        return false;
225	    for (const auto wg_status : m_wg_status) {
226	        if (wg_status == WG_STATUS_RUNNING)
227	            return true;
228	    }
229	    return false;
230	}
231	bool Kernel::is_dispatching() const { return is_activated() && !no_more_wg_to_dispatch(); }
232	
233	void Kernel::wg_finish(uint32_t wgid) {
234	    assert(is_wg_belonging(wgid));
235	    uint32_t idx = wgid - m_wgid_base;
236	    assert(m_wg_status[idx] == WG_STATUS_RUNNING);
237	    m_wg_status[idx] = WG_STATUS_FINISHED;
238	}
239	
240	bool Kernel::is_wg_belonging(uint32_t wg_id, uint32_t* wg_idx_in_kernel) const {
241	    if (!is_running() || is_finished())
242	        return false;
243	
244	    if (wg_id >= m_wgid_base && wg_id < m_wgid_base + get_num_wg()) {
245	        if (wg_idx_in_kernel) {
246	            *wg_idx_in_kernel = wg_id - m_wgid_base;
247	        }
248	        return true;
249	    } else {
250	        return false;
251	    }
252	}
