30	bool PhysicalMemory::write(paddr_t paddr, const void* data_, const bool mask[], uint64_t size) {
31	    const uint8_t* data = static_cast<const uint8_t*>(data_);
32	    paddr_t first_page_base = get_page_base(paddr);
33	    paddr_t first_page_end = first_page_base + m_pagesize - 1;
34	    if (paddr + size - 1 > first_page_end) {
35	        uint64_t size_this_copy = first_page_end - paddr + 1;
36	        if (!write(first_page_end + 1, data + size_this_copy, mask + size_this_copy, size - size_this_copy))
37	            return false;
38	        size = size_this_copy;
39	    }
40	    if (m_map.find(first_page_base) == m_map.end()) {
41	        if (m_auto_alloc) {
42	            page_alloc(first_page_base);
43	        } else {
44	            logger->critical("PMEM page at 0x{:x} not allocated, cannot write", paddr);
45	            return false;
46	        }
47	    }
48	    uint8_t* buf = m_map.at(first_page_base) + paddr - first_page_base;
49	    for (uint64_t i = 0; i < size; i++) {
50	        if (mask[i]) {
51	            buf[i] = data[i];
52	        }
53	    }
54	    return true;
55	}
56	
57	bool PhysicalMemory::write(paddr_t paddr, const void* data_, uint64_t size) {
58	    const uint8_t* data = static_cast<const uint8_t*>(data_);
59	    paddr_t first_page_base = get_page_base(paddr);
60	    paddr_t first_page_end = first_page_base + m_pagesize - 1;
61	    if (paddr + size - 1 > first_page_end) {
62	        uint64_t size_this_copy = first_page_end - paddr + 1;
63	        if (!write(first_page_end + 1, data + size_this_copy, size - size_this_copy))
64	            return false;
65	        size = size_this_copy;
66	    }
67	    if (m_map.find(first_page_base) == m_map.end()) {
68	        if (m_auto_alloc) {
69	            page_alloc(first_page_base);
70	        } else {
71	            logger->critical("PMEM page at 0x{:x} not allocated, cannot write", paddr);
72	            return false;
73	        }
74	    }
75	    uint8_t* buf = m_map.at(first_page_base) + paddr - first_page_base;
76	    std::memcpy(buf, data, size);
77	    return true;
78	}
79	
80	bool PhysicalMemory::read(paddr_t paddr, void* data_, uint64_t size) const {
81	    bool success = true;
82	    uint8_t* data = static_cast<uint8_t*>(data_);
83	    paddr_t first_page_base = get_page_base(paddr);
84	    paddr_t first_page_end = first_page_base + m_pagesize - 1;
85	    if (paddr + size - 1 > first_page_end) {
86	        uint64_t size_this_copy = first_page_end - paddr + 1;
87	        success = read(first_page_end + 1, data + size_this_copy, size - size_this_copy);
88	        size = size_this_copy;
89	    }
90	    if (m_map.find(first_page_base) == m_map.end()) {
91	        logger->error("PMEM page at 0x{:x} not allocated, read as all zero", paddr);
92	        std::memset(data, 0, size);
93	        return false;
94	    }
95	    uint8_t* buf = m_map.at(first_page_base) + paddr - first_page_base;
96	    std::memcpy(data, buf, size);
97	    return success;
98	}
