100	PhysicalMemory::~PhysicalMemory() {
101	    if(!m_auto_alloc && !m_map.empty()) {
102	        logger->warn("PMEM pages not freed before destruction");
103	    }
104	    for (auto& [paddr, ptr] : m_map) {
105	        delete[] ptr;
106	    }
107	}
