15	int cmdarg_kernel(std::string arg, std::function<void(std::shared_ptr<Kernel>)> new_kernel);
16	int cmdarg_dumpmem(std::string arg, std::vector<std::pair<paddr_t, paddr_t>>* dumpmem_ranges);
