20	int parse_arg(
21	    std::vector<std::string> args, ventus_rtlsim_config_t* config,
22	    std::function<void(std::shared_ptr<Kernel>)> new_kernel, std::vector<std::pair<paddr_t, paddr_t>>* dumpmem_ranges
23	) {
24	
25	    for (int argid = 0; argid < args.size(); argid++) {
26	        if (args[argid].starts_with("+verilator+")) {
27	            continue;
28	        }
29	        if (args[argid] == "-f") {
30	            if (++argid >= args.size()) {
31	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
32	            } else {
33	                std::filesystem::path filename, path_to_file, path_origin;
34	                try {
35	                    filename = std::filesystem::canonical(args[argid]);
36	                } catch (const std::filesystem::filesystem_error& e) {
37	                    std::cout << "Error: file not found: -f " << args[argid] << "\n" << e.what() << std::endl;
38	                    exit(1);
39	                }
40	                path_to_file = filename.parent_path();
41	                path_origin = std::filesystem::current_path();
42	                std::filesystem::current_path(path_to_file);
43	                std::ifstream file(filename);
44	                if (!file.is_open()) {
45	                    std::cout << "Error: file cannot open: -f " << args[argid] << std::endl;
46	                    exit(1);
47	                }
48	                std::vector<std::string> arguments;
49	                std::string line;
50	                while (std::getline(file, line)) {
51	                    // Ignore characters following '#' on each line
52	                    size_t sharp_pos = line.find('#');
53	                    if (sharp_pos != std::string::npos) {
54	                        line.erase(sharp_pos);
55	                    }
56	                    // Split the line into arguments based on spaces or other delimiters
57	                    std::istringstream iss(line);
58	                    std::string arg;
59	                    while (iss >> arg) {
60	                        arguments.push_back(arg);
61	                    }
62	                }
63	                parse_arg(arguments, config, new_kernel, dumpmem_ranges);
64	                std::filesystem::current_path(path_origin);
65	            }
66	        } else if (args[argid] == "--task") {
67	            if (++argid >= args.size()) {
68	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
69	            } else { // TODO
70	            }
71	        } else if (args[argid] == "--kernel") {
72	            if (++argid >= args.size()) {
73	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
74	            } else if (new_kernel) {
75	                if (cmdarg_kernel(args[argid], new_kernel)) {
76	                    cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.begin() + argid + 1));
77	                }
78	            }
79	        } else if (args[argid] == "--dump-mem") {
80	            if (++argid >= args.size()) {
81	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
82	            } else {
83	                if (cmdarg_dumpmem(args[argid], dumpmem_ranges)) {
84	                    cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.begin() + argid + 1));
85	                }
86	            }
87	        } else if (args[argid] == "--help") {
88	            cmdarg_help(0);
89	        } else if (args[argid] == "--sim-time-max") {
90	            if (++argid >= args.size()) {
91	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
92	            } else {
93	                uint64_t simtime = std::stoull(args[argid]);
94	                if (simtime <= 0) {
95	                    std::cout << "Error: --sim-time-max needs number > 0\n";
96	                    cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
97	                }
98	                config->sim_time_max = simtime;
99	            }
100	        } else if (args[argid] == "--waveform") {
101	            config->waveform.enable = true;
102	            config->waveform.time_begin = 0;
103	            config->waveform.time_end = -1;
104	        } else if (args[argid] == "--snapshot") {
105	            if (++argid >= args.size()) {
106	                cmdarg_error(std::vector<std::string>(args.begin() + argid - 1, args.end()));
107	            } else {
108	                uint64_t snapshot_time = std::stoull(args[argid]);
109	                config->snapshot.enable = (snapshot_time > 0);
110	                config->snapshot.time_interval = snapshot_time;
111	            }
112	        } else {
113	            cmdarg_error(std::vector<std::string>(args.begin() + argid, args.begin() + argid + 1));
114	        }
115	    }
116	    return 0;
117	}
