187	int cmdarg_dumpmem(std::string arg_raw, std::vector<std::pair<paddr_t, paddr_t>>* dumpmem_ranges) {
188	    if (!dumpmem_ranges)
189	        return 0;
190	    int len = arg_raw.size();
191	    auto arg = std::make_unique<char[]>(len + 1);
192	    strcpy(arg.get(), arg_raw.c_str());
193	
194	    paddr_t begin = 0, end = 0;
195	
196	    char* ptr1 = NULL;
197	    char* subarg = strtok_r(arg.get(), ",", &ptr1);
198	    if (subarg == nullptr) {
199	        std::cerr << "ERROR: --dump-mem missing first argument (address begin)" << std::endl;
200	        return -1;
201	    }
202	    try {
203	        begin = std::stoull(subarg, nullptr, 0);
204	    } catch (const std::invalid_argument& ia) {
205	        std::cerr << "ERROR: --dump-mem find invalid argument '" << subarg << "': " << ia.what() << std::endl;
206	        return -1;
207	    }
208	    subarg = strtok_r(NULL, ",", &ptr1);
209	    if (subarg == nullptr) {
210	        std::cerr << "ERROR: --dump-mem missing second argument (address end)" << std::endl;
211	        return -1;
212	    }
213	    try {
214	        end = std::stoull(subarg, nullptr, 0);
215	    } catch (const std::invalid_argument& ia) {
216	        std::cerr << "ERROR: --dump-mem find invalid argument '" << subarg << "': " << ia.what() << std::endl;
217	        return -1;
218	    }
219	    if (end < begin) {
220	        std::cerr << "ERROR: --dump-mem: address range invalid: begin(" << begin << ") > end(" << end << ")"
221	                  << std::endl;
222	        return -1;
223	    }
224	    dumpmem_ranges->push_back(std::make_pair(begin, end));
225	    return 0;
226	}
