57	static std::array<bool, 32> unpack_to_array(uint32_t v, size_t n) {
58	    std::bitset<32> bs(v);
59	    std::array<bool, 32> a{};
60	    for (size_t i = 0; i < n; ++i) {
61	        a[i] = bs[i]; // 保持一致：a[0] 对应最低位
62	    }
63	    return a;
64	}
