84	void gvm_t::getDutWarpNew() {
85	  for (const auto& item : g_cta2warp_data) {
86	    dut_active_warp_t d;
87	    d.sm_id = item.sm_id;
88	    d.hardware_warp_id = item.hardware_warp_id;
89	    d.software_wg_id = item.software_wg_id;
90	    d.software_warp_id = item.software_warp_id;
91	    d.xreg_base = item.sgpr_base;
92	    d.xreg_usage = g_sgprUsage; // 临时特殊处理
93	    // d.vreg_base = item.vgpr_base;
94	    d.base_dispatch_id_set = 0;
95	    d.wg_slot_id_in_warp_sche = item.wg_slot_id_in_warp_sche;
96	    d.num_thread = item.num_thread_in_warp;
97	
98	    // check if the warp is already in the list
99	    bool found_sw = false;
100	    bool found_hw = false;
101	    for (const auto& warp : dut_active_warps) {
102	      if (warp.second.software_wg_id == d.software_wg_id && warp.second.software_warp_id == d.software_warp_id) {
103	        found_sw = true;
104	      }
105	      if (warp.second.sm_id == d.sm_id && warp.second.hardware_warp_id == d.hardware_warp_id) {
106	        found_hw = true;
107	      }
108	    }
109	    if (found_sw) {
110	      logger->error("GVM error: repeated cta2warp dispatch with same software_wg_id {} & software_warp_id {}.\n",
111	        d.software_wg_id, d.software_warp_id);
112	      assert(0);
113	    }
114	    if (found_hw) {
115	      logger->error("GVM error: repeated cta2warp dispatch with same sm_id {} & hardware_warp_id {}.\n",
116	        d.sm_id, d.hardware_warp_id);
117	      assert(0);
118	    }
119	    dut_active_warps[{d.software_wg_id, d.software_warp_id}] = d;
120	  }
121	}
