154	void gvm_t::getDutInsnDispatch() {
155	  for (const auto& item : g_insn_dispatch_data) {
156	    insn_t d;
157	    d.pc = item.pc;
158	    d.insn = item.insn;
159	    d.extended = item.is_extended;
160	    d.care = isInsnCare(item.insn, retire_care_insns);
161	    d.done = 0;
162	    d.retired = 0;
163	    d.single_insn_cmp.care = isInsnCare(item.insn, single_insn_cmp_care_insns);
164	    d.single_insn_cmp.dut_done = 0;
165	    d.single_insn_cmp.ref_done = 0;
166	    d.single_insn_cmp.cmp_pass = 0;
167	    if (!d.single_insn_cmp.care) {
168	      d.single_insn_cmp.cmp_pass = 1; // 不关心的指令直接置为比对通过
169	    }
170	    d.dispatch_id = item.dispatch_id;
171	
172	    bool found = false;
173	    for (auto& warp : dut_active_warps) {
174	      if (warp.second.sm_id == item.sm_id && warp.second.hardware_warp_id == item.hardware_warp_id) {
175	        if (found) {
176	          printf("GVM error in `gvm_t::getDutInsnDispatch`: "
177	            "multiple item in `dut_active_warps` with same sm_id and hardware_warp_id\n");
178	          assert(0);
179	        }
180	        assert(warp.second.insns.find(d.dispatch_id) == warp.second.insns.end()); // 错误：指令已被 dispatch 过一次
181	        warp.second.insns[d.dispatch_id] = d;
182	        found = true;
183	        if (!warp.second.base_dispatch_id_set) {
184	          // 设置本 warp 的首条指令的 dispatch_id
185	          warp.second.base_dispatch_id = d.dispatch_id;
186	          warp.second.base_dispatch_id_set = 1;
187	          warp.second.next_retire_dispatch_id = d.dispatch_id;
188	        }
189	      }
190	    }
191	    // 目前获取 warp 结束的标志是 endprg dispatch，
192	    // 但这距离 endprg 真正执行完成还有一段时间，
193	    // 在此期间仍有其他指令会 dispatch，但 dut_active_warps 中的 warp 已经被删除了
194	  }
195	}
