259	void gvm_t::getDutVRegWbFinish() {
260	  for (const auto& item : g_vreg_wb_data) {
261	    assert(!isInsnCare(item.second.insn, barrier_insns));
262	    assert(!isInsnCare(item.second.insn, retire_care_insns));
263	    if (isInsnCare(item.second.insn, single_insn_cmp_care_insns)) {
264	      bool found_warp = false;
265	      for (auto& warp : dut_active_warps) {
266	        if ((warp.second.sm_id == item.second.sm_id) && (warp.second.hardware_warp_id == item.second.hardware_warp_id)) {
267	          found_warp = true;
268	          auto insn_it = warp.second.insns.find(item.second.dispatch_id);
269	          if (insn_it != warp.second.insns.end() && (insn_it->second.single_insn_cmp.dut_done != 1)) {
270	            // 如果找到了该条指令，并且该指令尚未被标记为已完成
271	            assert(insn_it->second.pc == item.second.pc);
272	            assert(insn_it->second.insn == item.second.insn);
273	            assert(insn_it->second.care == false); // 向量寄存器写回指令不参与 retire
274	            // 维护 single insn cmp 相关变量
275	            if (insn_it->second.single_insn_cmp.care == true) {
276	              insn_it->second.single_insn_cmp.dut_done = 1;
277	              insn_it->second.single_insn_cmp.dut_result.insn_type = InsnType::VREG;
278	              insn_it->second.single_insn_cmp.dut_result.vreg_result.rd = item.second.rd_data;
279	              insn_it->second.single_insn_cmp.dut_result.vreg_result.reg_idx = item.second.reg_idx;
280	              insn_it->second.single_insn_cmp.dut_result.vreg_result.mask = item.second.wvd_mask;
281	            }
282	          } else {
283	            logger->debug(
284	                "GVM info in `gvm_t::getDutVRegWbFinish`: "
285	                "sm_id & hardware_warp_id match successful, but no item in this warp's unfinished "
286	                "dispatched insns with required dispatch_id"
287	            );
288	            logger->debug(
289	                "getDutVRegWbFinish info: sm_id: {}, hardware_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: 0x{:08x}",
290	                item.second.sm_id, item.second.hardware_warp_id, item.second.dispatch_id, item.second.pc, item.second.insn
291	            );
292	            // assert(0);
293	          }
294	        }
295	      }
296	      if (!found_warp) {
297	        // logger->error("GVM error in `gvm_t::getDutVRegWbFinish`: "
298	        //   "no warp in `dut_active_warps` with required sm_id and hardware_warp_id\n"
299	        //   "getDutVRegWbFinish Error: sm_id: {}, hardware_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: 0x{:08x}",
300	        //   item.second.sm_id, item.second.hardware_warp_id, item.second.dispatch_id, item.second.pc, item.second.insn);
301	        // assert(0);
302	      }
303	    } else {
304	      logger->debug("GVM warning in `gvm_t::getDutVRegWbFinish`: "
305	        "ignoring VReg Writeback from pc 0x{:08x}, insn 0x{:08x}",
306	        item.second.pc, item.second.insn);
307	    }
308	  }
