350	void gvm_t::getDutXReg() {
351	  // 从交织的寄存器板块中，提取每个 warp 各自的寄存器
352	  std::map<uint32_t, std::map<uint32_t, XRegData>> g_xreg_data_mapped;
353	  assert(!g_xreg_data.empty());
354	  for (const auto& item : g_xreg_data) {
355	    g_xreg_data_mapped[item.sm_id][item.bank_id] = item;
356	  }
357	  for (auto& warp : dut_active_warps) {
358	    warp.second.curr_xreg.resize(warp.second.xreg_usage);
359	    // 将这个 warp 的寄存器从交织的板块中提取出来
360	    uint32_t num_bank = g_xreg_data_mapped[warp.second.sm_id].begin()->second.num_bank;
361	    assert((num_bank & (num_bank - 1)) == 0); // 断言 num_bank 是 2 的幂
362	    // 断言 warp 的寄存器是对齐到板块个数的
363	    assert(warp.second.xreg_base % num_bank == 0);
364	    assert(warp.second.xreg_usage % num_bank == 0);
365	    for (int i = 0; i < warp.second.xreg_usage; ++i) {
366	      warp.second.curr_xreg[i] = g_xreg_data_mapped[warp.second.sm_id]
367	        [(i + warp.second.hardware_warp_id) % num_bank].bank_data[(warp.second.xreg_base + i) >> __builtin_ctz(num_bank)];
368	    }
369	    warp.second.curr_xreg[0] = 0; // 强制 x0 为 0，认为 DUT 已经正确地对 x0 做了特殊处理
370	  }
371	}
