424	
425	void gvm_t::checkRetire() {
426	  for (auto& warp: dut_active_warps) {
427	    auto it = warp.second.insns.find(warp.second.next_retire_dispatch_id);
428	    assert(it == warp.second.insns.end() || it->second.retired == false);
429	
430	    if (it == warp.second.insns.end()) {
431	      continue;
432	    }
433	
434	    auto insn_it_begin = it;
435	    uint32_t final_cnt = 0;
436	    uint32_t temp_retire_cnt = 0;
437	    bool barriered = false;
438	    for (; it != warp.second.insns.end(); ++it) {
439	      if (it->second.care == false) {
440	        assert(isInsnCare(it->second.insn, barrier_insns) == false);
441	        temp_retire_cnt++;
442	      } else if (it->second.done == true) {
443	        final_cnt += temp_retire_cnt;
444	        temp_retire_cnt = 0;
445	        final_cnt++;
446	        if(isInsnCare(it->second.insn, barrier_insns)) {
447	          barriered = true;
448	          break;
449	        }
450	      } else {
451	        break;
452	      }
453	    }
454	    ++it;
455	    bool retiring = true;
456	    for (; it != warp.second.insns.end(); ++it) {
457	      if (barriered) {
458	        assert(it->second.care == false || it->second.done == false); // RTL 中，不应当有指令越过 barrier 完成
459	      }
460	      else if (it->second.care == true && it->second.done == true) {
461	        retiring = false;
462	        break;
463	      }
464	    }
465	    if (final_cnt == 0 || retiring == false) {
466	      continue;
467	    }
468	    retireInfo_t::retire_cnt_item_t r;
469	    r.sm_id = warp.second.sm_id;
470	    r.hardware_warp_id = warp.second.hardware_warp_id;
471	    r.software_wg_id = warp.second.software_wg_id;
472	    r.software_warp_id = warp.second.software_warp_id;
473	    r.retire_cnt = final_cnt;
474	    r.barrier_included = barriered;
475	    r.barrier_retry = false;
476	    retire_info.warp_retire_cnt.push_back(r);
477	
478	    logger->debug(fmt::format("GVM retire message from gvm_t::checkRetire()"));
479	
480	    // 打印 retire log（遍历最终 retire 的那一段）
481	    auto print_it = insn_it_begin;
482	    for (uint32_t i = 0; i < final_cnt && print_it != warp.second.insns.end(); ++i, ++print_it) {
483	      char insn_name[64];
484	      disasm(print_it->second.insn, insn_name);
485	      logger->debug(fmt::format(
486	        "GVM retire: sm_id: {}, hardware_warp_id: {}, software_wg_id: {}, software_warp_id: {}, dispatch_id: {}, pc: 0x{:08x}, insn: 0x{:08x} {}",
487	        warp.second.sm_id, warp.second.hardware_warp_id, warp.second.software_wg_id,
488	        warp.second.software_warp_id, print_it->second.dispatch_id, print_it->second.pc, print_it->second.insn, insn_name
489	      ));
490	    }
491	  }
492	}
493	
494	
495	void gvm_t::stepRef() {
496	  for (auto& item : retire_info.warp_retire_cnt) {
497	    // 分别步进 REF 的每个 warp
498	    auto warp_it = dut_active_warps.find({ item.software_wg_id, item.software_warp_id });
499	    assert(warp_it != dut_active_warps.end());
500	    assert(item.retire_cnt > 0);
501	
502	    for (int i=0; i<item.retire_cnt; i++) {
503	      gvmref_step_return_info_t gvmref_step_return_info;
504	
505	      auto& cur_insn = warp_it->second.insns[warp_it->second.next_retire_dispatch_id];
506	
507	      if (cur_insn.extended) {
508	        gvmref_step(item.software_wg_id, item.software_warp_id, &gvmref_step_return_info); // 跳过 regext
509	      }
510	
511	      // 确认 DUT 与 REF 的 PC 一致
512	      uint32_t next_gvmref_pc;
513	      next_gvmref_pc = gvmref_get_next_pc(item.software_wg_id, item.software_warp_id);
514	      uint32_t next_dut_pc;
515	      next_dut_pc = cur_insn.pc;
516	      if (next_dut_pc != next_gvmref_pc) {
517	        logger->error(fmt::format("GVM error: DUT and REF next PC mismatch on sm_id: {}, hardware_warp_id: {}, software_wg_id: {}, software_warp_id: {}. DUT next PC: 0x{:08x}, REF next PC: 0x{:08x}",
518	          item.sm_id, item.hardware_warp_id, item.software_wg_id, item.software_warp_id, next_dut_pc, next_gvmref_pc));
519	      }
520	      assert(next_dut_pc == next_gvmref_pc);
521	
522	      // 步进 REF 并维护 insn_t.single_insn_cmp
523	      gvmref_step(item.software_wg_id, item.software_warp_id, &gvmref_step_return_info);
524	      uint32_t next2_gvmref_pc = gvmref_get_next_pc(item.software_wg_id, item.software_warp_id);
525	      if (next2_gvmref_pc == next_gvmref_pc) {
526	        logger->debug(fmt::format("GVM info: REF PC not advanced after step on sm_id: {}, hardware_warp_id: {}, software_wg_id: {}, software_warp_id: {}. REF next PC before step: 0x{:08x}, after step: 0x{:08x}",
527	          item.sm_id, item.hardware_warp_id, item.software_wg_id, item.software_warp_id, next_gvmref_pc, next2_gvmref_pc));
528	        if (isInsnCare(cur_insn.insn, barrier_insns)) {
529	          assert(item.barrier_retry == false); // barrier_retry 应当只被置一次
530	          item.barrier_retry = true; // 该 warp 包含 barrier 指令，且 REF PC 未前进，标记 barrier_retry
531	        }
532	      }
533	      // assert(next2_gvmref_pc != next_gvmref_pc); // REF 的 PC 应当已经更新
534	
535	      if (cur_insn.single_insn_cmp.care) {
536	        // 若为 single_insn_cmp.care 的指令，则从 spike 返回值中提取指令执行结果
537	        switch (gvmref_step_return_info.insn_result.insn_type) {
538	          // 对于相同的指令类型，gvmref 认为的指令集合可为 RTL 认为的指令集合的子集
539	          case XREG:
540	            assert(cur_insn.single_insn_cmp.cmp_pass == 0);
541	            cur_insn.single_insn_cmp.ref_done = 1;
542	            cur_insn.single_insn_cmp.ref_result.insn_type = InsnType::XREG;
543	            cur_insn.single_insn_cmp.ref_result.xreg_result.rd =
544	              gvmref_step_return_info.insn_result.xreg_result.rd;
545	            cur_insn.single_insn_cmp.ref_result.xreg_result.reg_idx =
546	              gvmref_step_return_info.insn_result.xreg_result.reg_idx;
547	            break;
548	          case VREG:
549	            assert(cur_insn.single_insn_cmp.cmp_pass == 0);
550	            cur_insn.single_insn_cmp.ref_done = 1;
551	            cur_insn.single_insn_cmp.ref_result.insn_type = InsnType::VREG;
552	            cur_insn.single_insn_cmp.ref_result.vreg_result.rd =
553	              gvmref_step_return_info.insn_result.vreg_result.rd;
554	            cur_insn.single_insn_cmp.ref_result.vreg_result.reg_idx =
555	              gvmref_step_return_info.insn_result.vreg_result.reg_idx;
556	            cur_insn.single_insn_cmp.ref_result.vreg_result.mask =
557	              unpack_to_array(gvmref_step_return_info.insn_result.vreg_result.mask, warp_it->second.num_thread);
558	            break;
559	        }
560	        if (cur_insn.single_insn_cmp.ref_done == 0) {
561	          logger->debug(fmt::format("GVM warning: suspected dut and ref insn-type mismatch on pc: 0x{:08x}, insn: 0x{:08x}.",
562	            cur_insn.pc, cur_insn.insn)); // cmp care 但 ref 返回的 insn type 非 care
563	          volatile bool temp_flag = cur_insn.single_insn_cmp.ref_done;
564	        }
565	        cur_insn.single_insn_cmp.ref_done = 1;
566	        // 即便 gvmref_step_return_info.insn_result.insn_type 不在上面的 switch-case 中，也置为 ref_done = 1
567	        // 避免因 care == 1 但 ref_done 恒为 0 导致该条目永远无法删除
568	        // 在下面的 doSingleInsnCmp() 中会将其忽略而不进行比较（insn type switch-case 的 default）
569	      }
570	      if (!item.barrier_retry) {
571	        cur_insn.retired = true;
572	        warp_it->second.next_retire_dispatch_id++;
573	      }
574	    }
575	  }
576	  // 步进末尾的 barrier
577	  for (const auto& item : retire_info.warp_retire_cnt) {
578	    // 分别步进 REF 的每个 warp
579	    auto warp_it = dut_active_warps.find({ item.software_wg_id, item.software_warp_id });
580	    assert(warp_it != dut_active_warps.end());
581	
582	    if (item.barrier_included && item.barrier_retry) {
583	      gvmref_step_return_info_t gvmref_step_return_info;
584	      auto& cur_insn = warp_it->second.insns[warp_it->second.next_retire_dispatch_id];
585	      assert(!cur_insn.extended);
586	
587	      // 确认 DUT 与 REF 的 PC 一致
588	      uint32_t next_gvmref_pc;
589	      next_gvmref_pc = gvmref_get_next_pc(item.software_wg_id, item.software_warp_id);
590	      uint32_t next_dut_pc;
591	      next_dut_pc = cur_insn.pc;
592	      if (next_dut_pc != next_gvmref_pc) {
593	        logger->error(fmt::format("GVM error: DUT and REF next PC mismatch on sm_id: {}, hardware_warp_id: {}, software_wg_id: {}, software_warp_id: {}. DUT next PC: 0x{:08x}, REF next PC: 0x{:08x}",
594	          item.sm_id, item.hardware_warp_id, item.software_wg_id, item.software_warp_id, next_dut_pc, next_gvmref_pc));
595	      }
596	      assert(next_dut_pc == next_gvmref_pc);
597	
598	      // 步进 REF 并维护 insn_t.single_insn_cmp
599	      gvmref_step(item.software_wg_id, item.software_warp_id, &gvmref_step_return_info);
600	      uint32_t next2_gvmref_pc = gvmref_get_next_pc(item.software_wg_id, item.software_warp_id);
601	      if (next2_gvmref_pc == next_gvmref_pc) {
602	        logger->debug(fmt::format("GVM info: REF PC not advanced after step on sm_id: {}, hardware_warp_id: {}, software_wg_id: {}, software_warp_id: {}. REF next PC before step: 0x{:08x}, after step: 0x{:08x}",
603	          item.sm_id, item.hardware_warp_id, item.software_wg_id, item.software_warp_id, next_gvmref_pc, next2_gvmref_pc));
604	        logger->error("GVM error: REF PC not advanced after stepping over barrier instruction.");
605	        assert(0);
606	      }
607	      // assert(next2_gvmref_pc != next_gvmref_pc); // REF 的 PC 应当已经更新
608	
609	      assert(!cur_insn.single_insn_cmp.care);
610	      cur_insn.retired = true;
611	      warp_it->second.next_retire_dispatch_id++;
612	    }
613	  }
614	}
