616	int gvm_t::doSingleInsnCmp() {
617	  volatile int dut_active_warps_size = dut_active_warps.size();
618	  volatile auto dut_active_warps_begin = dut_active_warps.begin();
619	  volatile auto dut_active_warps_end = dut_active_warps.end();
620	  // assert(0);
621	  for (auto warpIt = dut_active_warps.begin(); warpIt != dut_active_warps.end(); ++warpIt) {
622	    for (auto insnIt = warpIt->second.insns.begin(); insnIt != warpIt->second.insns.end(); ++insnIt) {
623	      if (insnIt->second.single_insn_cmp.care) {
624	        if (insnIt->second.single_insn_cmp.dut_done && insnIt->second.single_insn_cmp.ref_done) {
625	          switch (insnIt->second.single_insn_cmp.dut_result.insn_type) {
626	            case InsnType::XREG: {
627	              assert(insnIt->second.single_insn_cmp.ref_result.insn_type == InsnType::XREG);
628	              if ((insnIt->second.single_insn_cmp.dut_result.xreg_result.rd
629	                != insnIt->second.single_insn_cmp.ref_result.xreg_result.rd)
630	                || (insnIt->second.single_insn_cmp.dut_result.xreg_result.reg_idx
631	                != insnIt->second.single_insn_cmp.ref_result.xreg_result.reg_idx)) {
632	                logger->error(fmt::format(
633	                  "GVM error: DUT and REF insn result mismatch at sm_id {}, hardware_warp_id {}, software_wg_id {}, software_warp_id {}, dispatch_id {}, pc 0x{:08x}, insn 0x{:08x}"
634	                  "insn_type XREG, DUT reg_idx: {}, REF reg_idx: {}, DUT rd: 0x{:08x}, REF rd: 0x{:08x}",
635	                  warpIt->second.sm_id, warpIt->second.hardware_warp_id, warpIt->second.software_wg_id,
636	                  warpIt->second.software_warp_id, insnIt->second.dispatch_id, insnIt->second.pc, insnIt->second.insn,
637	                  insnIt->second.single_insn_cmp.dut_result.xreg_result.reg_idx,
638	                  insnIt->second.single_insn_cmp.ref_result.xreg_result.reg_idx,
639	                  insnIt->second.single_insn_cmp.dut_result.xreg_result.rd,
640	                  insnIt->second.single_insn_cmp.ref_result.xreg_result.rd
641	                ));
642	                insnIt->second.single_insn_cmp.cmp_pass = -1;
643	              } else {
644	                insnIt->second.single_insn_cmp.cmp_pass = 1;
645	              }
646	              break;
647	            }
648	            case InsnType::VREG: {
649	              assert(insnIt->second.single_insn_cmp.ref_result.insn_type == InsnType::VREG);
650	              bool mask_same = std::equal(
651	                insnIt->second.single_insn_cmp.dut_result.vreg_result.mask.begin(),
652	                insnIt->second.single_insn_cmp.dut_result.vreg_result.mask.begin() + warpIt->second.num_thread,
653	                insnIt->second.single_insn_cmp.ref_result.vreg_result.mask.begin()
654	              );
655	              if ((insnIt->second.single_insn_cmp.dut_result.vreg_result.mask
656	                != insnIt->second.single_insn_cmp.ref_result.vreg_result.mask)
657	                || (!mask_same))
658	              {
659	                logger->error(fmt::format(
660	                  "GVM error: DUT and REF vreg insn result writeback mask or reg_idx mismatch at sm_id {}, hardware_warp_id {}, software_wg_id {}, software_warp_id {}, dispatch_id {}, pc 0x{:08x}, insn 0x{:08x}, "
661	                  "insn_type VREG, DUT reg_idx: {}, REF reg_idx: {}, DUT mask: {}, REF mask: {}, DUT reg_idx: {}, REF reg_idx: {}",
662	                  warpIt->second.sm_id, warpIt->second.hardware_warp_id, warpIt->second.software_wg_id,
663	                  warpIt->second.software_warp_id, insnIt->second.dispatch_id, insnIt->second.pc, insnIt->second.insn,
664	                  insnIt->second.single_insn_cmp.dut_result.vreg_result.reg_idx,
665	                  insnIt->second.single_insn_cmp.ref_result.vreg_result.reg_idx,
666	                  mask_to_string(insnIt->second.single_insn_cmp.dut_result.vreg_result.mask, warpIt->second.num_thread),
667	                  mask_to_string(insnIt->second.single_insn_cmp.ref_result.vreg_result.mask, warpIt->second.num_thread),
668	                  insnIt->second.single_insn_cmp.dut_result.vreg_result.reg_idx,
669	                  insnIt->second.single_insn_cmp.ref_result.vreg_result.reg_idx
670	                ));
671	                insnIt->second.single_insn_cmp.cmp_pass = -1;
672	              } else {
673	                bool is_fp32 = isInsnCare(insnIt->second.insn, fp32_vreg_insns);
674	                for (int i = 0; i < warpIt->second.num_thread; i++) {
675	                  if (insnIt->second.single_insn_cmp.dut_result.vreg_result.mask[i]) {
676	                    if (is_fp32) {
677	                      float dut_value = *reinterpret_cast<float*>(&insnIt->second.single_insn_cmp.dut_result.vreg_result.rd[i]);
678	                      float ref_value = *reinterpret_cast<float*>(&insnIt->second.single_insn_cmp.ref_result.vreg_result.rd[i]);
679	                      if (std::abs(dut_value - ref_value) > fp32_atol + fp32_rtol * std::abs(ref_value)) {
680	                        logger->error(fmt::format(
681	                          "GVM error: DUT and REF vreg-float mismatch at sm_id {}, hardware_warp_id {}, software_wg_id {}, software_warp_id {}, dispatch_id {}, pc 0x{:08x}, insn 0x{:08x}, "
682	                          "vreg_idx {}, vec_element_idx {}, DUT value: {}, REF value: {}",
683	                          warpIt->second.sm_id, warpIt->second.hardware_warp_id, warpIt->second.software_wg_id, warpIt->second.software_warp_id,
684	                          insnIt->second.dispatch_id, insnIt->second.pc, insnIt->second.insn,
685	                          insnIt->second.single_insn_cmp.dut_result.vreg_result.reg_idx,
686	                          i, dut_value, ref_value
687	                        ));
688	                        insnIt->second.single_insn_cmp.cmp_pass = -1;
689	                      }
690	                    } else {
691	                      if (insnIt->second.single_insn_cmp.dut_result.vreg_result.rd[i]
692	                        != insnIt->second.single_insn_cmp.ref_result.vreg_result.rd[i]) {
693	                        logger->error(fmt::format(
694	                          "GVM error: DUT and REF vreg mismatch at sm_id {}, hardware_warp_id {}, software_wg_id {}, software_warp_id {}, dispatch_id {}, pc 0x{:08x}, insn 0x{:08x}, "
695	                          "vreg_idx {}, vec_element_idx {}, DUT value: 0x{:08x}, REF value: 0x{:08x}",
696	                          warpIt->second.sm_id, warpIt->second.hardware_warp_id, warpIt->second.software_wg_id, warpIt->second.software_warp_id,
697	                          insnIt->second.dispatch_id, insnIt->second.pc, insnIt->second.insn,
698	                          insnIt->second.single_insn_cmp.dut_result.vreg_result.reg_idx,
699	                          i,
700	                          insnIt->second.single_insn_cmp.dut_result.vreg_result.rd[i],
701	                          insnIt->second.single_insn_cmp.ref_result.vreg_result.rd[i]
702	                        ));
703	                        insnIt->second.single_insn_cmp.cmp_pass = -1;
704	                      }
705	                    }
706	                  }
707	                }
708	                if (insnIt->second.single_insn_cmp.cmp_pass == 0) {
709	                  insnIt->second.single_insn_cmp.cmp_pass = 1; // 比对通过
710	                }
711	              }
712	              break;
713	            }
714	            default: {
715	              insnIt->second.single_insn_cmp.cmp_pass = -2; // unknown insn type
716	              break;
717	            }
718	          }
719	        }
720	      }
721	    }
722	  }
723	  return 0;
724	}
