55	class L1TlbAutoForward(SV: SVParam) extends L1TlbIO(SV, false){
56	  val tlb_req = RegInit(0.U.asTypeOf(io.in.bits))
57	  val tlb_rsp = RegInit(0.U(SV.paLen.W))
58	
59	  val s_idle :: s_check :: s_l2tlb_req :: s_l2tlb_rsp :: s_reply :: Nil = Enum(5)
60	  val nState = WireInit(s_idle)
61	  val cState = RegNext(nState)
62	
63	  io.l2_req.bits.asid := tlb_req.asid
64	  io.l2_req.bits.vpn := tlb_req.vaddr(SV.offsetLen-1, 0)
65	  io.out.bits.paddr := tlb_rsp
66	  io.in.ready := cState === s_idle || cState === s_reply
67	  io.out.valid := cState === s_reply
68	  io.l2_req.valid := cState === s_l2tlb_req
69	  io.l2_rsp.ready := cState === s_l2tlb_rsp
70	
71	  switch(cState){
72	    is(s_idle){
73	      when(io.in.fire){
74	        tlb_req := io.in.bits
75	        nState := s_l2tlb_req
76	      }.otherwise{ nState := s_idle}
77	    }
78	    is(s_l2tlb_req){
79	      when(io.l2_req.fire){
80	        nState := s_l2tlb_rsp
81	      }.otherwise{ nState := s_l2tlb_req }
82	    }
83	    is(s_l2tlb_rsp){
84	      when(io.l2_rsp.fire){
85	        nState := s_reply
86	        tlb_rsp := Cat(io.l2_rsp.bits.ppn, tlb_req.vaddr(SV.offsetLen-1, 0))
87	      }.otherwise{ nState := s_l2tlb_rsp }
88	    }
89	    is(s_reply){
90	      when(io.out.fire){
91	        nState := s_idle
92	        when(io.in.fire){
93	          tlb_req := io.in.bits
94	          nState := s_l2tlb_req
95	        }
96	      }.otherwise{ nState := s_reply }
97	    }
98	  }
99	}
