101	class L1TlbAutoReflect(SV: SVParam) extends L1TlbIO(SV, false){
102	  io.invalidate <> DontCare
103	  io.l2_req <> DontCare
104	  io.l2_rsp <> DontCare
105	  val s_idle :: s_reply :: Nil = Enum(2)
106	  val state = RegInit(s_idle)
107	  val reply = RegInit(0.U.asTypeOf(new L1TlbRsp(SV)))
108	  when(state === s_idle && io.in.fire) {
109	    state := s_reply
110	    reply.paddr := io.in.bits.vaddr
111	  }
112	  when(state === s_reply && io.out.fire) {
113	    state := s_idle
114	    reply := 0.U.asTypeOf(reply)
115	  }
116	  io.out.valid := state === s_reply
117	  io.in.ready := state === s_idle
118	  io.out.bits := reply
119	}
