121	class L1TLB(SV: SVParam, nWays: Int, Debug: Boolean = true) extends L1TlbIO(SV, Debug){
122	
123	  val storage = Reg(Vec(nWays, new L1TlbEntry(SV)))
124	  val avails = VecInit(storage.map(x => !x.flags(0)))
125	
126	  val s_idle :: s_check :: s_l2tlb_req :: s_l2tlb_rsp :: s_reply :: Nil = Enum(5)
127	  val nState = WireInit(s_idle)
128	  val cState = RegNext(nState)
129	
130	  io.in.ready := (cState === s_idle || cState === s_reply) && !io.invalidate.valid
131	
132	  val tlb_req = RegInit(0.U.asTypeOf(io.in.bits))
133	  val tlb_rsp = RegInit(0.U(SV.paLen.W))
134	
135	  val hitVec = VecInit(storage.map{ x =>
136	    (x.asid === tlb_req.asid) && (x.vpn === SV.getVPN(tlb_req.vaddr)) && x.flags(0)
137	  }).asUInt
138	  val hit = hitVec.orR
139	
140	  val replace = new PseudoLRU(nWays)
141	  val refillWay = Mux(avails.asUInt.orR, PriorityEncoder(avails), replace.way)
142	  val refillData = RegInit(0.U.asTypeOf(new L1TlbEntry(SV)))
143	
144	  val hitCnt = new Counter(200000)
145	  val missCnt = new Counter(200000)
146	  io.debug.foreach{ x =>
147	    dontTouch(x)
148	    x.hit_cnt := hitCnt.value
149	    x.miss_cnt := missCnt.value
150	  }
151	  when(io.invalidate.valid){
152	    storage.foreach{ e => when(e.asid === io.invalidate.bits.asid & e.flags(0)){ e := 0.U.asTypeOf(new L1TlbEntry(SV)) } }
153	  }
154	
155	  switch(cState){
156	    is(s_idle){
157	      when(io.in.fire){
158	        tlb_req := io.in.bits
159	        nState := s_check
160	      }.otherwise{ nState := s_idle }
161	    }
162	    is(s_check){
163	      when(hit){
164	        nState := s_reply
165	        replace.access(OHToUInt(hitVec))
166	        tlb_rsp := Cat(storage(OHToUInt(hitVec)).ppn, tlb_req.vaddr(SV.offsetLen-1, 0))
167	        hitCnt.inc
168	      }.otherwise{
169	        nState := s_l2tlb_req
170	        missCnt.inc
171	      }
172	    }
173	    is(s_l2tlb_req){
174	      when(io.l2_req.fire){
175	        nState := s_l2tlb_rsp
176	      }.otherwise{ nState := s_l2tlb_req }
177	    }
178	    is(s_l2tlb_rsp){
179	      when(io.l2_rsp.fire){
180	        storage(refillWay).vpn := SV.getVPN(tlb_req.vaddr)
181	        storage(refillWay).asid := tlb_req.asid
182	        tlb_rsp := Cat(io.l2_rsp.bits.ppn, tlb_req.vaddr(SV.offsetLen-1, 0))
183	        storage(refillWay).ppn := io.l2_rsp.bits.ppn
184	        storage(refillWay).flags := io.l2_rsp.bits.flags
185	        replace.access(refillWay)
186	        nState := s_reply
187	      }.otherwise{ nState := s_l2tlb_rsp }
188	    }
189	    is(s_reply){
190	      when(io.out.fire){
191	        tlb_req := 0.U.asTypeOf(tlb_req)
192	        nState := s_idle
193	        when(io.in.fire){
194	          tlb_req := io.in.bits
195	          nState := s_check
196	        }
197	      }.otherwise{ nState := s_reply }
198	    }
199	  }
200	  io.out.valid := cState === s_reply
201	  io.out.bits.paddr := tlb_rsp
202	  io.l2_req.valid := cState === s_l2tlb_req
203	  //io.l2_req.bits.ptbr := tlb_req.ptbr
204	  io.l2_req.bits.asid := tlb_req.asid
205	  io.l2_req.bits.vpn := SV.getVPN(tlb_req.vaddr)
206	
207	  io.l2_rsp.ready := cState === s_l2tlb_rsp
208	}

