78	    wdata := 0.U.asTypeOf(Vec(nWays, new L2TlbEntryA(SV)))
79	  }.otherwise{ wdata.foreach{ _ := io.write.bits.wdata }}
80	  val waymask = Mux(cState === s_reset, 0.U, io.write.bits.waymask)
81	
82	  when(cState === s_idle){
83	    when(io.invalidate.valid){
84	      nState := s_reset
85	      resetAsid := io.invalidate.bits
86	    }.elsewhen(io.write.valid){
87	      Entries.write(windex, VecInit(wdata.map(_.toBase._2)), waymask.asBools)
88	      for (((d, m), i) <- (wdata zip waymask.asBools).zipWithIndex) {
89	        when(m) {
90	          (AsidV(windex)(i).v zip d.flags).foreach{ case (v, f) => v := f(0) } // for each sector
91	          AsidV(windex)(i).asid := d.asid
92	        }
93	      }
94	    }
95	  }.elsewhen(cState === s_reset){ // Reset valid signal depends on ASID match (set by set
96	    AsidV(resetState).foreach{ av =>
97	      when(av.asid === resetAsid){
98	        av.v.foreach{ _ := false.B }
99	      }
100	    }
101	    when(resetFin){
102	      nState := s_idle
103	      resetAsid := 0.U
104	    }.otherwise{
105	      nState := s_reset
106	    }
107	  }
108	  // change the valid bit with Storage2
109	  val readTlbOut= {
110	    val raw = Entries.read(io.rindex)
111	    val out = Wire(Vec(nWays, new L2TlbEntryA(SV)))
112	    // for each way:
113	    ((raw zip out) zip AsidV(io.rindex)).foreach{ case ((r, o), av) =>
114	      o.viewAsSupertype(new L2TlbEntry(SV)) := r
115	      val x = Wire(Vec(nSectors, Vec(8, Bool())))
116	      x := VecInit(r.flags.map(x => VecInit(x.asBools)))
117	      (0 until nSectors).foreach{ i => x(i)(0) := r.flags(i)(0) & av.v(i) }
118	      o.flags := VecInit(x.map(_.asUInt))
119	      o.asid := av.asid
120	    }
121	    out
122	  }
123	  // bypass write to read
124	  val tlbOut = WireInit(readTlbOut)
125	  when(io.write.valid && windex === io.rindex){
126	    for(i <- 0 until nWays){
127	      tlbOut(i) := Mux(waymask(i), wdata(i), readTlbOut(i))
128	    }
129	  }
130	  io.ready := cState === s_idle
131	  io.tlbOut := tlbOut
132	}
