134	class L2TlbAccelStorage(SV: SVParam, _nWays: Int, level: Int) extends Module with L2TlbParam {
135	  def vpnSplit(vpn: UInt): (UInt, UInt) = {
136	    val sectorIdx: UInt = vpn(level * SV.idxLen + log2Up(nSectors) - 1, level * SV.idxLen)
137	    val vpnBase: UInt = Cat(
138	      vpn(vpn.getWidth-1, level * SV.idxLen + log2Up(nSectors)),
139	      0.U((level * SV.idxLen + log2Up(nSectors)).W)
140	    )
141	    (vpnBase, sectorIdx)
142	  }
143	  val io = IO(new Bundle{
144	    val accelReq = Vec(nBanks, Flipped(ValidIO(new Bundle{
145	      val asid = UInt(SV.asidLen.W)
146	      val vpn = UInt(SV.vpnLen.W)
147	    })))
148	    val accelOut = Vec(nBanks, ValidIO(UInt(SV.ppnLen.W)))
149	    val refill = Flipped(ValidIO(new L2TlbEntryA(SV)))
150	    val invalidate = Flipped(ValidIO(UInt(SV.asidLen.W)))
151	  })
152	  val Entries = Reg(Vec(_nWays, new L2TlbEntryA(SV)))
153	  val Valids = RegInit(VecInit(Seq.fill(_nWays)(false.B)))
154	  val replace = new RandomReplacement(_nWays)
155	  val replaceWay = Mux(Valids.reduce(_ && _), replace.get_replace_way(0.U), PriorityEncoder(Valids.map{!_}))
156	  (0 until nBanks).foreach{ b =>
157	    val accelReq_split = vpnSplit(io.accelReq(b).bits.vpn)
158	    val hitVec = VecInit((Entries zip Valids).map{ case(m, v) => // asid match + vpn match + sector valid
159	      m.asid === io.accelReq(b).bits.asid && vpnSplit(m.vpn)._1 === accelReq_split._1 && m.flags(accelReq_split._2)(0) && v
160	    })
161	    val hitWay = PriorityEncoder(hitVec)
162	    val hit = hitVec.asUInt =/= 0.U
163	
164	    // --- Output
165	    io.accelOut(b).valid := io.accelReq(b).valid && hit
166	    io.accelOut(b).bits := Mux(io.accelReq(b).valid && hit, Entries(hitWay).ppns(accelReq_split._2), 0.U(SV.ppnLen.W))
167	    // Output ---
168	  }
169	  when(io.invalidate.valid){
170	    (Entries zip Valids).foreach{ case(m, v) =>
171	      when(m.asid === io.invalidate.bits){
172	        m := 0.U.asTypeOf(m)
173	        v := false.B
174	      }
175	    }
176	  }.elsewhen(io.refill.valid){
177	    Entries(replaceWay) := io.refill.bits
178	    Valids(replaceWay) := true.B
179	    replace.get_next_state(0.U, 0.U)
180	  }
181	}
