216	class L2TLB(
217	  SV: SVParam,
218	  Debug: Boolean = false,
219	  L2C: Option[L2cache.InclusiveCacheParameters_lite] = None,
220	  accelSize: Int = 8,
221	)(
222	  implicit val L1C: Option[L1Cache.HasRVGParameters]
223	)
224	  extends Module with L2TlbParam {
225	  assert(log2Ceil(nBanks) == log2Floor(nBanks))
226	  override def nSectors: Int = L2C match {
227	    case Some(l2c) => l2c.beatBytes / (SV.xLen / 8) // beatBytes = 32 << 2 =128
228	    case None => super.nSectors
229	  }
230	  val io = IO(new Bundle{
231	    val in = Vec(nBanks, Flipped(DecoupledIO(new L2TlbReq(SV))))
232	    val invalidate = Flipped(ValidIO(new Bundle{
233	      val asid = UInt(SV.asidLen.W)
234	    }))
235	    val out = Vec(nBanks, DecoupledIO(new L2TlbRsp(SV)))
236	    // Request Always Read!
237	    val mem_req = L2C match {
238	      case Some(l2c) => Vec(nBanks, DecoupledIO(new TLBundleA_lite(l2c))) // interconnect with xbar
239	      case None => Vec(nBanks, DecoupledIO(new Cache_Req(SV)))
240	    }
241	    val mem_rsp = Flipped(L2C match {
242	      case Some(l2c) => Vec(nBanks, DecoupledIO(new TLBundleD_lite(l2c))) // interconnect with xbar
243	      case None => Vec(nBanks, DecoupledIO(new Cache_Rsp(SV)))
244	    })
245	    val asid_req = Output(Vec(nBanks, UInt(SV.asidLen.W)))
246	    val ptbr_rsp = Flipped(Vec(nBanks, Valid(UInt(SV.xLen.W))))
247	  })
248	
249	  val storageArray = Seq.fill(nBanks)(Module(new L2TlbStorage(SV)))
250	  val accelStorageArray = (1 until SV.levels).map{ i => Module(new L2TlbAccelStorage(SV, accelSize, i))}
251	  val accelOut_delay = accelStorageArray.map{ a => RegNext(a.io.accelOut) }
252	  val accelRefillArb = (1 until SV.levels).map{i => Module(new RRArbiter(new L2TlbEntryA(SV), nBanks)) }
253	  accelRefillArb.foreach{ a =>
254	    dontTouch(a.io.in)
255	    a.io.out.ready := true.B
256	  }
257	
258	  val walker = Module(new PTW(SV, nBanks, false, L2C))
259	
260	  val replace = Seq.fill(nBanks)(new SetAssocLRU(nSets/nBanks, nWays, "lru"))
261	  val refillIndex = RegInit(VecInit(Seq.fill(nBanks)(0.U(log2Up(nSets).W))))
262	  val refillWay = VecInit((storageArray zip replace).map{ case(s, r) => Mux(s.io.wAvail.orR, PriorityEncoder(s.io.wAvail), r.way(s.io.write.bits.windex))})
263	
264	  val refillData = Seq.fill(nBanks)(RegInit(0.U.asTypeOf(new L2TlbEntryA(SV))))
265	
266	  val s_idle :: s_check :: s_ptw_req :: s_ptw_rsp :: s_reply :: s_invalid :: Nil = Enum(6)
267	  val nextState = WireInit(VecInit(Seq.fill(nBanks)(s_idle)))
268	  val curState = nextState.map(RegNext(_))
269	
270	  val cnt = new Counter(200000)
271	  val level_cnt = Seq.fill(nBanks)(RegInit(VecInit(Seq.fill(SV.levels+1)(0.U(18.W)))))
272	  val level_cnt_next = Wire(Vec(nBanks, Vec(SV.levels+1, UInt(18.W))))
273	  level_cnt_next := level_cnt
274	  val total_cnt_next = level_cnt_next.reduceLeft[Vec[UInt]]{ case (ls, rs) =>
275	    VecInit((ls zip rs).map{ case(l, r) => l + r })
276	  }
277	
278	  (0 until nBanks).foreach{ i =>
279	    val in = io.in(i)
280	    val out = io.out(i)
281	    val cState = curState(i)
282	    val nState = nextState(i)
283	    val storage = storageArray(i)
284	    val ptw_req = walker.io.ptw_req(i)
285	    val ptw_rsp = walker.io.ptw_rsp(i)
286	    val asid_req = io.asid_req(i)
287	    val ptbr_rsp = io.ptbr_rsp(i)
288	
289	    in.ready := cState === s_idle && !io.invalidate.valid
290	
291	    val tlb_req = RegInit(0.U.asTypeOf(in.bits))
292	    storage.io.rindex := tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).setIndex
293	    val storage_rsp = storage.io.tlbOut // Bundle{vpn, ppn: Vec(nSectors, UInt), flags: Vec(nSectors, UInt)}
294	    val tlb_rsp = RegInit(0.U.asTypeOf(out.bits))
295	
296	    val hitVec = VecInit(storage_rsp.map(m =>
297	      m.flags(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)(0)
298	        && (m.vpn.asTypeOf(vpnL2TlbBundle(SV)).tag === tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).tag)
299	        && (m.asid === tlb_req.asid)
300	    )).asUInt
301	    assert(PopCount(hitVec) <= 1.U)
302	    val hit = cState === s_check && hitVec.orR
303	    val miss = cState === s_check && !hitVec.orR
304	
305	    // for SV39 VA {VPN2, VPN1, VPN0}:
306	    //   accelStorage(1) checks VPN2 and gives out level = 2 when match (2 walks to go)
307	    //   accelStorage(0) checks {VPN2, VPN1} and gives out level = 1 when match (1 walk to go)
308	    //   hit checks whole vpn and gives out level = 0 when match
309	    //   nothing match will gives out level = 3
310	    val accelLevel_pre = PriorityEncoder((hit +: accelStorageArray.map(_.io.accelOut(i).valid)) :+ true.B)
311	    val accelLevel = RegNext(accelLevel_pre)
312	    (0 until SV.levels-1).foreach{ j => // j for selecting level, i for selecting walker ways / tlb banks
313	      accelStorageArray(j).io.accelReq(i).valid := curState(i) === s_check
314	      accelStorageArray(j).io.accelReq(i).bits.asid := tlb_req.asid
315	      accelStorageArray(j).io.accelReq(i).bits.vpn := tlb_req.vpn
316	
317	      val refill_level = walker.io.accel_fill(i).bits.cur_level
318	      accelRefillArb(j).io.in(i).valid := walker.io.accel_fill(i).valid && refill_level === j.U
319	      accelRefillArb(j).io.in(i).bits.asid := tlb_req.asid
320	      accelRefillArb(j).io.in(i).bits.vpn := accelStorageArray(j).vpnSplit(tlb_req.vpn)._1
321	      accelRefillArb(j).io.in(i).bits.level := i.U //! likely unused at all, since var j has stands for the level
322	      accelRefillArb(j).io.in(i).bits.ppns := Mux(accelRefillArb(j).io.in(i).valid, walker.io.accel_fill(i).bits.ppns, 0.U.asTypeOf(accelRefillArb(j).io.in(i).bits.ppns))
323	      accelRefillArb(j).io.in(i).bits.flags := Mux(accelRefillArb(j).io.in(i).valid, walker.io.accel_fill(i).bits.flags, 0.U.asTypeOf(accelRefillArb(j).io.in(i).bits.flags))
324	
325	      accelStorageArray(j).io.refill := accelRefillArb(j).io.out
326	      accelStorageArray(j).io.invalidate.valid := io.invalidate.valid
327	      accelStorageArray(j).io.invalidate.bits := io.invalidate.bits.asid
328	    }
329	    val accelPA = MuxLookup(accelLevel, 0.U)(
330	      (1 to SV.levels).map(_.U) zip
331	        (accelOut_delay.map{a => Cat(a(i).bits, 0.U(SV.offsetLen.W))} :+ ptbr_rsp.bits)
332	    )
333	
334	    ptw_req.bits.source := tlb_req.id
335	    ptw_req.bits.vpn := tlb_req.vpn
336	    ptw_req.bits.paddr := accelPA
337	    ptw_req.bits.curlevel := accelLevel - 1.U
338	    ptw_req.valid := cState === s_ptw_req
339	
340	    ptw_rsp.ready := storage.io.ready && cState === s_ptw_rsp
341	    storage.io.write.valid := RegNext(cState === s_ptw_rsp && ptw_rsp.fire) // s_ptw_rsp -> [s_reply]
342	    storage.io.write.bits.waymask := UIntToOH(refillWay(i))
343	    storage.io.write.bits.wdata := refillData(i)
344	    storage.io.write.bits.windex := refillIndex(i)
345	
346	    out.bits := tlb_rsp
347	    out.valid := cState === s_reply
348	
349	    storage.io.invalidate.valid := io.invalidate.valid
350	    storage.io.invalidate.bits := io.invalidate.bits.asid
351	
352	    asid_req := tlb_req.asid
353	
354	    switch(cState){
355	      is(s_idle){
356	        when(io.invalidate.valid){
357	          nState := s_invalid
358	        }.elsewhen(in.fire){
359	          tlb_req := in.bits
360	          when(storage.io.ready && !io.invalidate.valid) {
361	            nState := s_check
362	          }.otherwise{
363	            nState := s_ptw_req
364	            refillData(i).asid := in.bits.asid
365	            refillData(i).vpn := in.bits.vpn
366	          }
367	        }
368	      }
369	      is(s_check){
370	        (0 until SV.levels - 1).foreach{ j =>
371	          accelStorageArray(j).io.accelReq(i).bits.asid := tlb_req.asid
372	          accelStorageArray(j).io.accelReq(i).bits.vpn := tlb_req.vpn
373	          accelStorageArray(j).io.accelReq(i).valid := true.B
374	        }
375	        when(hit){
376	          replace(i).access(storage.io.rindex, hitVec)
377	          tlb_rsp.id := tlb_req.id
378	          tlb_rsp.ppn := storage_rsp(OHToUInt(hitVec)).ppns(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
379	          tlb_rsp.flag := storage_rsp(OHToUInt(hitVec)).flags(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
380	          nState := s_reply
381	        }.otherwise{
382	          nState := s_ptw_req
383	          refillData(i).asid := tlb_req.asid
384	          // aligned vpn:
385	          refillData(i).vpn := Cat(tlb_req.vpn(SV.vpnLen-1, log2Up(nSectors)), 0.U(log2Up(nSectors).W))
386	          refillData(i).level := SV.levels.U
387	        }
388	      }
389	      is(s_ptw_req){
390	        when(ptw_req.fire){
391	          nState := s_ptw_rsp
392	        }.otherwise{ nState := s_ptw_req }
393	      }
394	      is(s_ptw_rsp){
395	        when(ptw_rsp.fire){
396	          refillIndex(i) := tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).setIndex
397	          refillData(i).ppns := ptw_rsp.bits.ppns
398	          refillData(i).flags := ptw_rsp.bits.flags
399	          replace(i).access(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).setIndex, refillWay(i))
400	
401	          tlb_rsp.id := tlb_req.id
402	          tlb_rsp.ppn := ptw_rsp.bits.ppns(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
403	          tlb_rsp.flag := ptw_rsp.bits.flags(tlb_req.vpn.asTypeOf(vpnL2TlbBundle(SV)).sectorIndex)
404	          nState := s_reply
405	        }.otherwise{ nState := s_ptw_rsp }
406	      }
407	      is(s_reply){
408	        refillData(i) := 0.U.asTypeOf(refillData(i))
409	        when(out.fire){ nState := s_idle }.otherwise{ nState := s_reply }
410	      }
411	      is(s_invalid){
412	        when(storage.io.ready){
413	          nState := s_idle
414	        }.otherwise{
415	          nState := s_invalid
416	        }
417	      }
418	    }
419	
