493	  extends Module with L2TlbParam {
494	  val num_l1 = L1C match {
495	    case Some(x) => x.NSms * x.NCacheInSM
496	    case None => n_l1
497	  }
498	  val num_l2 = nBanks
499	  val io = IO(new Bundle{
500	    val req_l1 = Flipped(Vec(num_l1, DecoupledIO(new L2TlbReq(SV))))
501	    val req_l2 = Vec(num_l2, DecoupledIO(new L2TlbReq(SV)))
502	    val rsp_l1 = Vec(num_l1, DecoupledIO(new L2TlbRsp(SV)))
503	    val rsp_l2 = Flipped(Vec(num_l2, DecoupledIO(new L2TlbRsp(SV))))
504	  })
505	  if(num_l1 == 1){
506	    for(j <- 0 until num_l2){
507	      val req_bank_idx = io.req_l1(0).bits.vpn.asTypeOf(vpnL2TlbBundle(SV)).bankIndex
508	      io.req_l2(j).valid := io.req_l1(0).valid && req_bank_idx === j.U
509	      io.req_l2(j).bits := io.req_l1(0).bits
510	      if(req_bank_idx.getWidth == 0)
511	        io.req_l2(j).bits.id := 1.U(1.W)
512	      else
513	        io.req_l2(j).bits.id := Cat(req_bank_idx(log2Ceil(nBanks)-1, 0), 1.U(1.W))
514	      io.req_l1(0).ready := (VecInit(io.req_l2.map(_.ready)).asUInt)(req_bank_idx)
515	    }
516	  }
517	  else {
518	    val arb_req = Seq.fill(num_l2)(Module(new RRArbiter(new L2TlbReq(SV), num_l1)))
519	    for (i <- 0 until num_l1;
520	         j <- 0 until num_l2) {
521	      val req_bank_idx = io.req_l1(i).bits.vpn.asTypeOf(vpnL2TlbBundle(SV)).bankIndex
522	
523	      arb_req(j).io.in(i).valid := io.req_l1(i).valid && req_bank_idx === j.U
524	      arb_req(j).io.in(i).bits := Mux(io.req_l1(i).valid && req_bank_idx === j.U, io.req_l1(i).bits, 0.U.asTypeOf(new L2TlbReq(SV)))
525	      if(req_bank_idx.getWidth == 0)
526	        arb_req(j).io.in(i).bits.id := Cat(i.U(log2Ceil(num_l1).W), 1.U(1.W))
527	      else
528	        arb_req(j).io.in(i).bits.id := Cat(req_bank_idx(log2Ceil(nBanks)-1, 0), i.U(log2Ceil(num_l1).W), 1.U(1.W))
529	      io.req_l1(i).ready := (VecInit(arb_req.map {
530	        _.io.in(i).ready
531	      }).asUInt)(req_bank_idx)
532	
533	      io.req_l2(j) <> arb_req(j).io.out
534	    }
535	  }
536	
537	  if(num_l2 == 1){
538	    for(i <- 0 until num_l1){
539	      val reply_id = (io.rsp_l2(0).bits.id >> 1)(log2Ceil(num_l1) - 1, 0)
540	      io.rsp_l1(i).valid := io.rsp_l2(0).valid
541	      io.rsp_l1(i).bits := io.rsp_l2(0).bits
542	      io.rsp_l2(0).ready := (VecInit(io.rsp_l1.map(_.ready)).asUInt)(reply_id)
543	    }
544	  }
545	  else {
546	    val arb_rsp = Seq.fill(num_l1)(Module(new RRArbiter(new L2TlbRsp(SV), num_l2)))
547	    for (i <- 0 until num_l1;
548	         j <- 0 until num_l2) {
549	
550	      val reply_id = (io.rsp_l2(j).bits.id >> 1)(log2Ceil(num_l1) - 1, 0)
551	
552	      arb_rsp(i).io.in(j).valid := io.rsp_l2(j).valid && reply_id === i.U
553	      arb_rsp(i).io.in(j).bits := Mux(io.rsp_l2(j).valid && reply_id === i.U, io.rsp_l2(j).bits, 0.U.asTypeOf(new L2TlbRsp(SV)))
554	      io.rsp_l2(j).ready := (VecInit(arb_rsp.map{
555	        _.io.in(j).ready}
556	      ).asUInt)(reply_id)
557	
558	      io.rsp_l1(i) <> arb_rsp(i).io.out
559	    }
560	  }
561	}
562	// send to L2C port by parseAddress()
563	class L2TlbToL2CacheXBar(
564	  SV: SVParam,
565	  nL2CReqPort: Int,
566	  L2C: L2cache.InclusiveCacheParameters_lite)
567	(
568	  implicit val L1C: L1Cache.HasRVGParameters
569	)extends Module
570	  with L2TlbParam{
571	  val nTlbMemPort = nBanks
572	  val io = IO(new Bundle{
573	    val req_tlb = Vec(nTlbMemPort, Flipped(DecoupledIO(new TLBundleA_lite(L2C))))
574	    val rsp_tlb = Vec(nTlbMemPort, DecoupledIO(new TLBundleD_lite(L2C)))
575	    val req_cache = Vec(nL2CReqPort, DecoupledIO(new TLBundleA_lite(L2C)))
576	    val rsp_cache = Vec(nL2CReqPort, Flipped(DecoupledIO(new TLBundleD_lite_plus(L2C))))
577	  })
578	  if(nTlbMemPort == 1){
579	    for(j <- 0 until nL2CReqPort){
580	      val req_idx = L2C.parseAddress(io.req_tlb(0).bits.address)._2
581	      io.req_cache(j).valid := io.req_tlb(0).valid & req_idx === j.U
582	      io.req_cache(j).bits := Mux(io.req_tlb(0).valid & req_idx === j.U, io.req_tlb(0).bits, 0.U.asTypeOf(new TLBundleA_lite(L2C)))
583	      io.req_tlb(0).ready := (VecInit(io.req_cache.map(_.ready)).asUInt)(req_idx)
584	    }
585	  }
586	  else{
587	    val arb_req = Seq.fill(nL2CReqPort)(Module(new RRArbiter(new TLBundleA_lite(L2C), nTlbMemPort)))
588	    for (i <- 0 until nTlbMemPort;
589	         j <- 0 until nL2CReqPort){
590	      val req_idx = L2C.parseAddress(io.req_tlb(i).bits.address)._2
591	      arb_req(j).io.in(i).valid := io.req_tlb(i).valid & req_idx === j.U
592	      arb_req(j).io.in(i).bits := Mux(io.req_tlb(i).valid & req_idx === j.U, io.req_tlb(i).bits, 0.U.asTypeOf(new TLBundleA_lite(L2C)))
593	      io.req_tlb(i).ready := (VecInit(arb_req.map{
594	        _.io.in(i).ready
595	      }).asUInt)(req_idx)
596	      io.req_cache(j) <> arb_req(j).io.out
597	    }
598	  }
599	  if(nL2CReqPort == 1){
600	    val reply_id = (io.rsp_cache(0).bits.source >> (1 + log2Ceil(L1C.NSms)))(log2Ceil(nTlbMemPort) - 1, 0)
601	    for(i <- 0 until nTlbMemPort) {
602	      io.rsp_tlb(i).valid := io.rsp_cache(0).valid & reply_id === i.U
603	      io.rsp_tlb(i).bits := Mux(io.rsp_cache(0).valid & reply_id === i.U, io.rsp_cache(0).bits, 0.U.asTypeOf(new TLBundleD_lite_plus(L2C)))
604	      io.rsp_cache(0).ready := (VecInit(io.rsp_tlb.map(_.ready)).asUInt)(reply_id)
605	    }
606	  }
607	  else{
608	    val arb_rsp = Seq.fill(nTlbMemPort)(Module(new RRArbiter(new TLBundleD_lite(L2C), nL2CReqPort)))
609	    for (i <- 0 until nTlbMemPort;
610	         j <- 0 until nL2CReqPort) {
611	      val reply_id = (io.rsp_cache(j).bits.source >> (1 + log2Ceil(L1C.NSms)))(log2Ceil(nTlbMemPort)-1, 0)
612	      arb_rsp(i).io.in(j).valid := io.rsp_cache(j).valid & reply_id === i.U
613	      arb_rsp(i).io.in(j).bits := Mux(io.rsp_cache(j).valid & reply_id === i.U, io.rsp_cache(j).bits, 0.U.asTypeOf(new TLBundleD_lite_plus(L2C)))
614	      io.rsp_cache(j).ready := (VecInit(arb_rsp.map{
615	        _.io.in(j).ready
616	      }).asUInt)(reply_id)
617	      io.rsp_tlb(i) <> arb_rsp(i).io.out
618	    }
619	  }
620	}
